import{_ as t,c as a,o as r,ag as o}from"./chunks/framework.Sr95JMjc.js";const p=JSON.parse('{"title":"안정적으로 투자하는 방법","description":"","frontmatter":{"layout":"home","title":"안정적으로 투자하는 방법","date":"2025-06-01T22:00+09:00","tags":["분산투자","ETF","TDF"],"sidebar":false},"headers":[],"relativePath":"investment/index.md","filePath":"investment/index.md","lastUpdated":1779403721000}'),n={name:"investment/index.md"};function s(i,e,l,d,f,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<p>기본적인 저축부터 연금저축 그리고 ISA 투자까지 알아보았다. 저축과 투자의 비중은 나의 소득에 따라 결정된다고 이해했다. 불필요한 소비를 줄이고 저축을 하면서 목돈을 모으고, 조금씩 모아지는 자금으로 투자함으로써 부가적인 운용 수익을 버는 것이 내가 해야할 일이다. 그렇다면, 그동안 주식이나 코인에 투자해본 적이 없던 내가 안정적인 투자를 위해서 알아야하는 건 무엇일까?</p><h2 id="분산투자" tabindex="-1">분산투자 <a class="header-anchor" href="#분산투자" aria-label="Permalink to &quot;분산투자&quot;">​</a></h2><p>투자 포트폴리오 구성의 기본은 분산 투자이다. <a href="https://www.tossbank.com/articles/four-seasons-portfolio" target="_blank" rel="noreferrer">안정적인 투자를 위해</a> 동일한 상품이나 섹터에 집중적인 투자를 하지 않고 <a href="https://www.tossbank.com/articles/portfolio-diversification" target="_blank" rel="noreferrer">다양하게 구성하는 것</a>을 말한다. 주식과 채권 그리고 금 등 위험자산과 안전자산의 투자 비중을 분산하는 것이다. 그런데, 바쁜 직장인이 투자에 대한 직접 포트폴리오를 구성하고 매주 정보를 수집한 것을 투자에 반영하는 리밸런싱 과정은 현실적으로 어려운 일이다. 그래서 자산운용사가 포트폴리오를 구성해서 운용해주는 ETF 또는 TDF 상품에 투자하는 것이 권장된다.</p><h3 id="적립식-투자" tabindex="-1">적립식 투자 <a class="header-anchor" href="#적립식-투자" aria-label="Permalink to &quot;적립식 투자&quot;">​</a></h3><p>나는 투자할 수 있는 시드머니가 준비되어있지 않으므로 기본적으로 투자에 사용될 ISA 계좌와 연금저축 그리고 IRP 계좌에 모두 입금하기 보다는 투자금과 비상금을 일단 파킹통장과 CMA 계좌에 분산해서 거치해두는게 좋을 것 같다. 언제든지 비정기적인 지출에 사용할 수 있어야하고 필요할때마다 <code>매주 조금씩 적립식으로 투자해야</code>한다.</p><h2 id="etf" tabindex="-1">ETF <a class="header-anchor" href="#etf" aria-label="Permalink to &quot;ETF&quot;">​</a></h2><p><a href="https://www.tigeretf.com/ko/education/etf_justice/content.do" target="_blank" rel="noreferrer">ETF(상장지수펀드)</a>는 개별 채권이나 주식에 직접적인 투자하는 게 아니라 자산 운용사가 구성해놓은 포트폴리오에 주식처럼 투자할 수 있는 펀드 상품이다. <a href="https://www.youtube.com/watch?v=2V5py_3mUuo" target="_blank" rel="noreferrer">만능 통장으로 부르고 있는 ISA 계좌</a> 뿐만 아니라 연금저축 그리고 IRP에 납입된 적립금으로도 투자할 수 있는 대표적인 금융 상품이다. 채권형 ETF부터 배당형 ETF 그리고 파킹형 ETF 등 다양한 ETF 상품들이 상장되고 있다.</p><h2 id="tdf" tabindex="-1">TDF <a class="header-anchor" href="#tdf" aria-label="Permalink to &quot;TDF&quot;">​</a></h2><p><a href="https://www.fundguide.net/Fund/TDF" target="_blank" rel="noreferrer">TDF(Target Date Fund)</a>는 투자자의 은퇴 시점을 기준으로 생애 주기에 맞춰 자산 운용사가 알아서 자산 배분 비중을 두어 분산 투자해주는 상품이다. 주식과 투자에 대해 경험이 많은 사람이라면 직접 포트폴리오를 구성해서 운용하는게 더 좋겠지만 저와 같이 투자에 관심이 없던 직장인들에게는 <code>연금저축과 IRP 계좌에 납입한 적립금</code>으로는 TDF 상품 하나만을 매수해두는게 더 좋은 선택 같다. 또한, TDF 상품은 출생년도에 60을 더해서 나온 값과 가까운 것이 이름에 포함된 것을 선택하면 되니까 간단하다. 예를 들어, 저는 1992년생으로 <a href="https://www.funetf.co.kr/search?schVal=tdf2050" target="_blank" rel="noreferrer">TDF2050 상품을 선택</a>하면 된다.</p><hr><p>올해 예상되는 경제성장률도 1% 이하로 내려가면서 한국은행이 <a href="https://www.youtube.com/watch?v=ezjbS8vztfg" target="_blank" rel="noreferrer">기준금리를 2.50%로 인하</a>했다. 과거 사회초년생이었던 시기에 1% 였던 저금리 시대로 돌아가고 있다. 비록 서울은 아니지만 내집 마련을 앞두고 있으니 뒤늦게나마 재테크에 관심이 많아지고 있다. 아무튼, 현재 보유하고 있는 자산을 과도하게 투자는 하지 않은 예정이다. 그래서 월급의 10%는 원래 소득이 아니라고 생각하고 ISA 계좌와 연금저축 그리고 IRP 계좌에 적립하는 것으로 계획을 변경했다.</p>',11)])])}const _=t(n,[["render",s]]);export{p as __pageData,_ as default};
